-- FT-008: tree-scoped metadata for presigned photo uploads.
--
-- Image bytes live in the object store (S3, or an S3-compatible service locally);
-- this table records what was uploaded, by whom, for what, and whether the server
-- has verified and cleaned it. Storage keys are generated by the server, never
-- supplied by a client.
--
-- person.profile_media_id and citation.media_id have existed since V1 as plain
-- uuid columns with no foreign key, and no route has ever set them (FT-002
-- rejected a citation mediaId). This migration:
--   1. stops with diagnostics if any row already has a value there, since such a
--      value can't point at a media row (no silent fixing);
--   2. creates media;
--   3. adds same-tree composite foreign keys from both columns to media, and makes
--      each media row attachable at most once.

-- 1. Preflight -----------------------------------------------------------------

do $$
declare
    problems text := '';
    bad      text;
begin
    select string_agg(x.id::text, ', ') into bad from (
        select id from person where profile_media_id is not null order by 1 limit 20
    ) x;
    if bad is not null then
        problems := problems || E'\n  person with a profile_media_id: ' || bad;
    end if;

    select string_agg(x.id::text, ', ') into bad from (
        select id from citation where media_id is not null order by 1 limit 20
    ) x;
    if bad is not null then
        problems := problems || E'\n  citation with a media_id: ' || bad;
    end if;

    if problems <> '' then
        raise exception 'FT-008 preflight found media references with no media table to resolve them (up to 20 ids per check):%', problems
            using hint = 'Clear or fix these values explicitly, then restart so Flyway re-runs V6. '
                      || 'Nothing was changed: the migration rolled back.';
    end if;
end
$$;

-- 2. media --------------------------------------------------------------------

create table media (
    id                     uuid        primary key,
    tree_id                uuid        not null references tree (id),
    -- What the upload may be attached to (MediaPurpose in :core).
    purpose                text        not null
        constraint media_purpose_check check (purpose in ('PROFILE_PHOTO', 'CITATION_SCAN')),
    -- PENDING: presigned, unverified, never readable. READY: verified and cleaned.
    -- REJECTED: not a supported image or not the declared size; final.
    status                 text        not null default 'PENDING'
        constraint media_status_check check (status in ('PENDING', 'READY', 'REJECTED')),
    -- Declared at presign time, confirmed from the bytes when READY.
    content_type           text        not null
        constraint media_content_type_check check (content_type in ('image/jpeg', 'image/png')),
    -- The exact size the client declared; the uploaded object must match it.
    -- 20971520 = MediaRules.MAX_UPLOAD_BYTES (20 MiB).
    upload_byte_size       bigint      not null
        constraint media_upload_byte_size_check check (upload_byte_size between 1 and 20971520),
    -- Where the unverified upload goes (private, deleted after finalization).
    upload_key             text        not null constraint media_upload_key_key unique,
    -- Where the cleaned image is stored; set when READY.
    storage_key            text        constraint media_storage_key_key unique,
    byte_size              bigint,
    width                  integer,
    height                 integer,
    sha256                 text,
    uploaded_by_account_id uuid        not null references account (id),
    created_at             timestamptz not null default now(),
    finalized_at           timestamptz,
    version                bigint      not null default 1,
    constraint media_id_tree_id_key unique (id, tree_id),
    constraint media_ready_details_check check (
        status <> 'READY' or (
            storage_key is not null and byte_size is not null and width is not null
            and height is not null and sha256 is not null and finalized_at is not null
        )
    ),
    constraint media_storage_key_only_when_ready_check check (status = 'READY' or storage_key is null)
);

create index media_tree_id_idx on media (tree_id);

-- 3. Same-tree references, each media row attached at most once ---------------
-- Composite FKs use MATCH SIMPLE: a null reference (no photo, no scan) skips the check.
-- The person constraint is deferred to commit so a merge can hand the retired
-- person's photo to the survivor before the retired row is deleted (FT-007).

alter table person
    add constraint person_profile_media_same_tree_fkey
        foreign key (profile_media_id, tree_id) references media (id, tree_id),
    add constraint person_profile_media_id_key
        unique (profile_media_id) deferrable initially deferred;

alter table citation
    add constraint citation_media_same_tree_fkey
        foreign key (media_id, tree_id) references media (id, tree_id),
    add constraint citation_media_id_key unique (media_id);
